"""Build the independent PokeBonk section; does not rewrite Megabonk pages."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[1]
BASE='https://megabonk.org'
A='/assets/pokebonk/'
P='/pokebonk/'
DATE='October 23, 2026'
VERSION='v0.8.25'
CLIENT='https://pokebonk.com/assets/main-C90gB5C0-mvjzbutg.js'
NEWS='https://pokebonk.com/assets/news-SYOogixF-mvjzbutg.js'
EN='https://pokebonk.com/assets/en-D7CrqP_e-mvjzbutg.js'

def ext(url,label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (external website, opens in a new tab)</span></a>'
def ref(n): return f'<sup class="ref"><a href="#source-{n}" aria-label="Source {n}">[{n}]</a></sup>'
def table(head,rows):
    return '<div class="table-wrap" role="region" aria-label="Comparison table" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{h}</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,title,text): return f'<section id="{id}"><h2>{title}</h2>{text}</section>'
def source_list(items):
    return '<section class="sources" id="sources"><h2>Sources &amp; verification</h2><ol>'+''.join(f'<li id="source-{i}">{ext(url,label)} — {desc}</li>' for i,(url,label,desc) in enumerate(items,1))+'</ol><a class="back" href="#guide">Back to guide ↑</a></section>'
def related(items):
    return '<section class="related"><h2>Continue exploring</h2>'+''.join(f'<a href="{P+slug}">{label} →</a>' for slug,label in items)+'</section>'

NAV=[('Play',P+'play/'),('Start here',P+'beginners-guide/'),('Starters',P+'starters/'),('Guides',P+'#guides'),('Mobile',P+'mobile/'),('中文',P+'zh/beginners-guide/')]
def navlinks(path):
    return ''.join(f'<a href="{u}"'+(' class="nav-play"' if u==P+'play/' else '')+(' aria-current="page"' if path==u else '')+'>'+('<span aria-hidden="true">▶</span> ' if u==P+'play/' else '')+f'{label}</a>' for label,u in NAV)
def shell(path,title,desc,body,image='forest-1280.webp',lang='en',noindex=False,script=''):
    advertising = '' if noindex or path in [P+'about/',P+'contact/',P+'privacy/'] else '<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
    alternates=''
    if path in [P+'beginners-guide/',P+'zh/beginners-guide/']:
        alternates=f'<link rel="alternate" hreflang="en" href="{BASE+P}beginners-guide/"><link rel="alternate" hreflang="zh-Hans" href="{BASE+P}zh/beginners-guide/"><link rel="alternate" hreflang="x-default" href="{BASE+P}beginners-guide/">'
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
{advertising}<title>{title}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="{BASE+path}">
{('<meta name="robots" content="noindex,follow">' if noindex else '')}{alternates}
<meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE+A+image}"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="{A}favicon.ico" sizes="any"><link rel="icon" type="image/svg+xml" href="{A}favicon.svg"><link rel="apple-touch-icon" href="{A}apple-touch-icon.png"><link rel="stylesheet" href="{A}site.css"><link rel="stylesheet" href="{A}layout.css">
<link rel="preload" href="{A}nunito-800-latin.woff2" as="font" type="font/woff2" crossorigin>
{f'<script src="{A+script}" defer></script>' if script else ''}<link rel="stylesheet" href="/assets/guide-article-layout.css"></head><body class="pb-layout guide-layout">
<a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="{P}"><img src="{A}logo.svg" width="44" height="44" alt=""><span>PokeBonk<small>Field notes by Megabonk.org</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{navlinks(path)}</nav><details class="mobile-nav"><summary>Menu <span aria-hidden="true">☰</span></summary><nav class="mobile-links" aria-label="Mobile navigation">{navlinks(path)}</nav></details></div></header>
<main id="main" class="wrap">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>PokeBonk field notes</strong><p>An independent player guide on Megabonk.org. Not affiliated with Charcher, Nintendo, The Pokémon Company, Creatures or GAME FREAK. Pokémon names and game artwork belong to their respective owners.</p><a href="/">Back to the Megabonk Wiki →</a></div><nav aria-label="Site information"><a href="{P}about/">About</a><a href="{P}contact/">Contact</a><a href="{P}privacy/">Privacy</a></nav></div></footer></body></html>'''

PAGES={}
def article(slug,title,h1,desc,answer,parts,sources,links,image=None,lang='en',script=''):
    path=P+slug+'/'
    toc='<aside class="toc" aria-label="On this page"><strong>On this page</strong>'+''.join(f'<a href="#{id}">{label}</a>' for id,label,_ in parts)+'<a href="#sources">Sources</a></aside>'
    figure=f'<figure><img src="{A}forest-1280.webp" width="1280" height="672" loading="lazy" alt="PokeBonk promotional forest with a waterfall and stone altar"><figcaption>Official promotional artwork © Charcher / respective rights holders. Not a gameplay screenshot.</figcaption></figure>'
    if image:
        figure=f'<figure><img src="{A}guest-menu-1280.webp" srcset="{A}guest-menu-800.webp 800w, {A}guest-menu-1280.webp 1280w" sizes="(max-width:900px) 100vw, 760px" width="1280" height="889" alt="PokeBonk guest entry screen with Guest, Enter and Create account tabs" loading="lazy"><figcaption>Original game entry screen, captured {DATE}. © Charcher / respective rights holders. Menu inspection; no completed gameplay test.</figcaption></figure>'
    body=f'<nav class="crumbs" aria-label="Breadcrumb"><a href="{P}">PokeBonk</a> / {h1}</nav><header class="article-head" id="guide"><span class="tag">Independent player guide</span><h1>{h1}</h1><p class="answer">{answer}</p><p class="meta">Checked {DATE} · Beta {VERSION} · Source-based guide</p></header><div class="article-layout"><article class="prose">'+figure+''.join(section(*part) for part in parts)+source_list(sources)+related(links)+'</article>'+toc+'</div>'
    PAGES[path]={'title':title,'desc':desc,'html':shell(path,title,desc,body,image='guest-menu-1280.webp' if image else 'forest-1280.webp',lang=lang,script=script)}

controls=table(['Action','Current default','When to use it'],[
('Move','<kbd>W A S D</kbd>','Move while checking the camera direction.'),('Jump / slide','<kbd>Space</kbd> / <kbd>Left Shift</kbd>','Separate movement actions; check readiness and terrain.'),('Interact','<kbd>E</kbd>','Use the prompt beside a nearby object.'),('Ultimate','<kbd>R</kbd>','Activate when ready; <kbd>Y</kbd> toggles auto Ultimate.'),('Aim / lock','<kbd>Q</kbd> / right mouse','Change aiming mode or target lock.'),('Map / pause','<kbd>M</kbd> / <kbd>P</kbd>','Inspect the map or pause before reading.'),('Upgrade tools','<kbd>F</kbd> / <kbd>X</kbd> / <kbd>Z</kbd>','Reroll / skip / banish in the level-up context, when available.')])

article('beginners-guide','PokeBonk Beginner Guide: First Run, Controls & Saves','Your first PokeBonk run',
'Start PokeBonk at the original browser game, check current controls, choose your first partner and protect Guest progress before changing devices.',
f'Open the original browser game, enter through Guest or your existing account, then choose a partner and prepare a run. Check your controls before chasing a build: PokeBonk uses its own Pokémon kits and progression.{ref(1)}',[
('entry','Start at the original game',f'<p>Go to {ext("https://pokebonk.com/?lang=en","pokebonk.com — original game")}. The entry screen offers <strong>Guest</strong>, <strong>Enter</strong> and <strong>Create account</strong>. Use Enter for an existing named account. The Guest screen says progress is saved on the server and tied to the current device.{ref(1)}</p><ol><li>If you already have progress, use that same browser profile first.</li><li>For a new Guest, select Guest and use “Play as a guest!”.</li><li>On a fresh profile, follow the starter selection. On an existing profile, continue into the League through Play.</li><li>Read the chosen partner’s passive and move kit. Confirm the partner, then inspect the available region, mode and difficulty before starting.</li></ol><p class="note">The entry screen was inspected on October 23. The later sequence is documented in the public client; this guide does not claim a successful Guest creation or completed run in this review.</p>'),
('controls','Keep the current controls nearby',f'<p>These are defaults in the v0.8.25 client. Saved rebindings take priority. Open Settings and its Keys section if an action differs; level-up shortcuts are contextual, not ordinary attack keys.{ref(2)}</p>'+controls+'<p>Your equipped moves attack automatically. Movement, camera control, aiming and upgrade decisions still need attention. Use pause to read rather than testing unfamiliar shortcuts in a crowded wave.</p>'),
('upgrades','Read the first upgrade by what it changes',f'<p>Level-up choices can add or improve a move or change a stat. Read the full card and the current move slots before confirming. A new move, an upgrade to an existing move and a stat bonus are different decisions in the current client.{ref(2)}</p><ul><li><strong>Need recovery?</strong> Check whether the offer actually restores HP or changes regeneration; extra damage is a different effect.</li><li><strong>Improving damage?</strong> Compare the affected damage class and move type with your current kit.</li><li><strong>Managing movement?</strong> Learn what the current mobility option does before replacing a choice that already works for you.</li></ul><p>This is a card-reading method, not a tested universal spending order. Available choices and their value depend on the run.</p>'),
('save','Protect the Guest you already have',f'<p>The project’s policy says unused Guest accounts are deleted after 60 days. Local browser storage keeps session information; a server-saved run does not mean a different browser automatically has the credentials to access it.{ref(3)}</p><p>Before clearing site data or switching profiles, inspect the original game’s option to save the existing Guest to an account. Keep your current session until the conversion is confirmed. We have not tested conversion, recovery or the inactivity deadline.</p><p>For missing progress, keep the displayed version and error text and use {ext("https://discord.gg/X7KusQqx8X","the project’s Discord support")}. This guide cannot recover or access game accounts.</p>'),
('questions','Before the next run','<h3>Do I need to download it?</h3><p>The original entry is a browser game. No installer is needed for that route.</p><h3>Is it a Megabonk mod?</h3><p>It has a separate website, client and account system. Start it through PokeBonk, rather than a Megabonk mod manager.</p><h3>Which starter should I pick?</h3><p>Use the role you want to learn: recovery with Bulbasaur, defensive bonuses with Squirtle, or a Fire-focused kit with Charmander. These are passive-based suggestions, not measured win rates.</p>')],
[('https://pokebonk.com/?lang=en','Original game entry','Entry menus inspected October 23, 2026; Beta v0.8.25. SINGLE_SOURCE.'),(CLIENT,'Original public game client','Current menu flow, input defaults and upgrade contexts; build mvjzbutg. Client inspection is not a gameplay benchmark.'),('https://pokebonk.com/legal','Project legal & privacy notice','Guest inactivity and browser storage policy, accessed October 23. Policy not retention-tested.')],
[('starters/','Choose your first partner'),('mobile/','Playing on a phone'),('zh/beginners-guide/','中文入门攻略')],image=True)

article('mobile','PokeBonk Mobile: Android, iPhone & APK Guide','PokeBonk on your phone',
'Find the original PokeBonk browser route for Android and iPhone, understand touch controls and check APK claims without risking your Guest session.',
f'Try the original browser game before looking for an APK. The current client includes touch controls, but source support is not proof that every Android phone or iPhone can run a full session smoothly.{ref(1)}',[
('open','Use the browser route first',f'<p>Open {ext("https://pokebonk.com/?lang=en","pokebonk.com — original browser game")} on the phone you intend to use. JavaScript and WebGL are required by the project’s entry page. Start with the device’s current browser rather than a reposted game inside another app.{ref(1)}</p><ol><li>Keep an existing Guest in its original browser profile. Do not clear it as a first troubleshooting step.</li><li>Let the game load, then rotate to landscape if portrait leaves the controls cramped.</li><li>Check movement, camera and the visible action buttons before committing to a longer run.</li><li>Read the current graphics options if performance is poor; reduce workload one setting at a time and compare the result.</li></ol><p class="note">This is a source-based mobile setup guide. We did not test a physical iPhone or Android device, measure FPS, or verify a minimum supported OS or RAM specification.</p>'),
('touch','What the touch layout changes',f'<p>The current client defines an on-screen movement stick and touch actions for movement skills, interaction, aiming and Ultimate. It also includes touch settings and graphics controls. These definitions establish available controls; they do not establish device compatibility.{ref(2)}</p>'+table(['Task','Phone check','If it does not work'],[('Movement','Move with the on-screen stick.','Check whether touch controls are enabled and the playfield is focused.'),('Camera','Try the camera area away from buttons.','Separate camera gestures from action taps; inspect the current controls menu.'),('Interaction','Look for the contextual action.','Get within prompt range; an absent prompt is different from an unresponsive button.'),('Reading upgrades','Check labels at landscape width.','Pause or change layout before selecting; do not guess from clipped text.')])+'<p>Keyboard advice such as “press R” describes the desktop default. On a phone, use the corresponding displayed button rather than assuming there is a physical-key requirement.</p>'),
('apk','Android APK and iPhone download questions',f'<p>The project describes a browser release, and its legal notice says the game is not distributed on other platforms. In this source check we did not verify an official Android APK or App Store release.{ref(3)}</p><p>A third-party wrapper can open the same website while remaining an independent app. A familiar icon or name does not establish authorship. Before installing anything, check whether the original project explicitly links to that exact release. The browser route needs no APK.</p><p>If your browser offers Add to Home Screen, that is a browser shortcut or web-app flow; it is not evidence of a separately published native version. That flow was not device-tested here.</p>'),
('problems','Choose the next step by the symptom',f'<p>The original page requires JavaScript/WebGL and includes a Retry recovery action for failed client loading. Its recovery code reloads game resources rather than asking the player to erase all site data.{ref(1)}{ref(2)}</p>'+table(['What you see','Next check','Evidence boundary'],[('Page says JavaScript or WebGL is needed','Check browser settings and whether 3D graphics work in that browser.','A prerequisite check; not a confirmed fix for every device.'),('Menu loads but play is slow','Inspect graphics quality and resolution options; compare a lower workload.','No measured speedup or universal best setting.'),('Retry screen or failed resource loading','Use the displayed Retry action and record a repeated error.','Original client recovery flow; not an account reset.'),('Guest appears missing','Return to the original browser/profile before changing data.','Account recovery is not verified by this guide.')])+f'<p>If the problem persists, report device model, browser version, game version and the visible error to {ext("https://discord.gg/X7KusQqx8X","PokeBonk community support")}. Do not send passwords.</p>')],
[('https://pokebonk.com/?lang=en','Original browser entry','JavaScript/WebGL prerequisite and current entry, October 23.'),(CLIENT,'Original public game client','Touch, graphics options and recovery-related UI; v0.8.25. SINGLE_SOURCE; no real-device test.'),('https://pokebonk.com/legal','Project release and privacy notice','Browser distribution and session policy, October 23.')],
[('beginners-guide/','First-run setup and saves'),('starters/','Compare the starters'),('multiplayer/','Online features and co-op status')])

starter_rows='''<div class="table-wrap" role="region" aria-label="Starter roles" tabindex="0"><table><thead><tr><th scope="col">Partner</th><th scope="col">Listed passive</th><th scope="col">Four-move kit</th><th scope="col">Choose for</th></tr></thead><tbody>
<tr data-goal="recovery"><td><strong>Bulbasaur</strong><br>Grass / Poison</td><td>+1.5 regeneration; +25% healing; Grass attacks heal 0.4% max HP per hit, up to five times per second.</td><td>Vine Whip · Razor Leaf · Sleep Powder · Solar Beam</td><td>Recovery and learning a mixed kit.</td></tr>
<tr data-goal="defense"><td><strong>Squirtle</strong><br>Water</td><td>+15 armor; +20 shield; +40% damage below 40% HP.</td><td>Water Gun · Bubble · Rapid Spin · Hydro Pump</td><td>Defensive bonuses while learning movement.</td></tr>
<tr data-goal="fire"><td><strong>Charmander</strong><br>Fire</td><td>+10% Fire damage; +40% damage below 40% HP.</td><td>Ember · Fire Spin · Flamethrower · Fire Blast</td><td>A Fire-focused upgrade direction.</td></tr></tbody></table></div>'''

article('starters','PokeBonk Starters: Compare Roles, Moves & Passives','Choose your first partner',
'Compare Bulbasaur, Squirtle and Charmander in PokeBonk by current passives, move kits and learning goals, with clear limits on strength rankings.',
f'Choose Bulbasaur for listed recovery, Squirtle for armor and shield, or Charmander for a Fire-focused kit. These recommendations interpret the current passives; they are not a tested PokeBonk tier list or a claim about the strongest endgame Pokémon.{ref(1)}',[
('compare','Compare the three starter roles',f'<p>The current League definitions mark these three as starters and assign the kits below. The table combines those definitions with the client’s passive text. A listed kit is not proof that every move is equipped at the beginning of a run.{ref(1)}{ref(2)}</p><div class="filter"><label for="goal">What would you like to learn?</label><br><select id="goal"><option value="all">Compare all roles</option><option value="recovery">Recovery</option><option value="defense">Defensive bonuses</option><option value="fire">Fire-focused damage</option></select><output id="choice" aria-live="polite">Compare all three below. These are playstyle recommendations, not tested strength tiers.</output></div>'+starter_rows),
('decision','Make the choice from the problem you have', '<h3>Taking several small hits: inspect Bulbasaur</h3><p>Regeneration and Grass-hit healing give a clear recovery direction. The heal depends on eligible hits and has a rate limit. Do not read the percentage as unlimited healing for every visual projectile or as permission to stand still.</p><h3>Learning to avoid contact: inspect Squirtle</h3><p>Armor and shield provide defensive bonuses without a low-HP activation requirement. The extra damage does have a low-HP requirement. Choose for the defensive part if you are learning; deliberately taking damage is a separate, untested tradeoff.</p><h3>Learning a focused damage kit: inspect Charmander</h3><p>The listed kit uses Fire moves, making the passive’s Fire bonus straightforward to relate to the cards you read. Its conditional damage bonus does not establish a higher clear rate or safer opening than the other two.</p>'),
('tier-list','What a PokeBonk tier list would need','<p>There is no measured S/A/B ordering on this page. A meaningful performance ranking needs a stated version, map, difficulty, permanent upgrades and a comparable set of runs. Attack stats, listed move damage or type coverage alone leave out survival, crowd patterns and actual uptime.</p><p>Use this comparison to choose a learning goal now. To compare results later, keep map and difficulty fixed, record permanent upgrades and note why the run ended. That produces a useful personal comparison without pretending that three unrelated runs establish a global meta.</p>'),
('progress','Keep first choice, evolution and unlocking separate',f'<p>The current League records include challenges for adding other starter members. For these starters the displayed challenge is to complete two runs, win or lose. Challenge progress and capture are separate parts of League acquisition in the public client; do not assume the challenge text alone grants every member.{ref(2)}</p><p>Evolution inside a run is another system. The species dataset contains evolution fields, but a general species table alone is not enough to promise the exact runtime evolution conditions for every partner. Read the current League profile and in-run prompt before planning around a level copied from another Pokémon game.</p>')],
[(CLIENT,'Original public game client','Passive modifiers and descriptions, build mvjzbutg, October 23. SINGLE_SOURCE; recommendations are editorial, not win-rate evidence.'),(NEWS,'Original League definitions in the shared game bundle','Starter flags, four-move kits and challenge text, current build; not a measured ranking.')],
[('beginners-guide/','Prepare your first run'),('megabonk-vs-pokebonk/','Coming from Megabonk'),('mobile/','Set up mobile play')],script='starter-choice.js')

article('multiplayer','PokeBonk Multiplayer: Clans, Friends & Co-op Status','PokeBonk multiplayer: what is confirmed?',
'Separate PokeBonk clans, friends and leaderboards from shared co-op runs, with current source limits and a checklist for verifying new releases.',
f'Clans, friends and online leaderboards are documented in the current client. A working shared co-op run was not verified in this review. Do not treat an online account, a clan invite or a visible friend as proof that you can enter the same arena together.{ref(1)}',[
('confirmed','Online features are different player tasks',f'<p>The project’s account notice documents saved progress, rankings, clans and trainer profiles. The current client also includes friends and invitations. These are concrete online services, but their presence does not establish real-time shared combat.{ref(1)}{ref(2)}</p>'+table(['Feature','What the current sources support','What it does not establish'],[('Friends','Friend requests, online presence and social notices.','A shared combat session.'),('Clans','Membership, messages and shared competitive activity.','A player-hosted co-op lobby.'),('Leaderboards','Submitted records and trainer profiles.','Live PvP or a simultaneous arena.'),('Shared co-op run','Not verified in this review.','No launch date or player limit is promised here.')])+'<p class="note">Source scope: v0.8.25, inspected October 23. This is a statement about what we verified, not a claim that an undocumented feature can never exist.</p>'),
('friends','If your goal is to play alongside friends', '<p>First agree which task you mean. If you want to compare records or take part in clan activity, use the relevant social menu in the original game. If you want everyone in one arena, require a visible shared-session flow before making plans around it.</p><ol><li>Check that everyone is on the same original game and current build.</li><li>Use the Friends or Clan features for their stated purpose; read whether the action adds a friend, invites a member or joins a run.</li><li>For a new co-op announcement, look for host/join instructions, eligibility and the actual session entry point.</li><li>If no shared-run action is present, ask the project’s support rather than following instructions for a different game.</li></ol><p>A trainer name is enough for many social actions. A friend does not need your password or browser session.</p>'),
('release','How to verify a new co-op claim',f'<p>Read the original game’s current What’s new panel and compare the version shown below the logo with {ext("https://pokebonk.com/version.json","the project’s current version record")}. A version record identifies a build; it does not by itself announce multiplayer support.{ref(3)}</p><p>Look for a dated project announcement that explicitly names shared runs, then follow its actual entry steps. We did not verify a co-op player cap, cross-play guarantee, PvP mode or release date from the sources inspected. Old roadmap estimates should not be written as launch dates.</p><p>For a current answer from the project, use {ext("https://discord.gg/X7KusQqx8X","PokeBonk Discord support")}. Keep the game version with the question so the answer is tied to the same client.</p>'),
('megabonk','Is this the Megabonk multiplayer mod?','<p>No: this guide covers the separate PokeBonk browser project. Megabonk mod instructions describe a different game and installation path. Installing a Megabonk co-op mod does not add a PokeBonk shared session.</p><p>If the video you watched uses Steam, a mod manager or Megabonk character names, check the game identity before following it. The PokeBonk starting point here is pokebonk.com.</p>')],
[(CLIENT,'Original public game client','Friends, clan and ranking UI, v0.8.25. SINGLE_SOURCE; shared co-op was not tested or established.'),('https://pokebonk.com/legal','Project account & privacy notice','Online account, clan and profile services, October 23.'),('https://pokebonk.com/version.json','Original current version record','Version 0.8.25 / build mvjzbutg when checked. Does not itself prove a feature launch.')],
[('beginners-guide/','Start at the original game'),('mobile/','Phone access and APK questions'),('megabonk-vs-pokebonk/','Separate the two games')])

article('megabonk-vs-pokebonk','PokeBonk vs Megabonk: Which Game Are You Looking For?','PokeBonk vs Megabonk',
'Find the Pokémon-style browser survivor you saw in a clip, compare it with Megabonk and choose the right game, account and guide before you start.',
f'If you searched “Megabonk Pokémon”, the game you want may be PokeBonk: a separate browser fan project. Megabonk is vedinad’s Steam game. They share the broad horde-survival idea, but they have different clients, progression and guides.{ref(1)}{ref(2)}',[
('compare','Start with the entry point',table(['Question','PokeBonk','Megabonk'],[('Where do I open it?',ext('https://pokebonk.com/?lang=en','Original browser game'),ext('https://store.steampowered.com/app/3405340/Megabonk/','Megabonk on Steam')),('Who is behind it?','Fan project by Charcher.','Developed and published by vedinad.'),('What am I choosing?','A Pokémon League partner with a passive and move kit.','A character and a growing build of weapons, Tomes and items.'),('How do I access progress?','Guest or game account; session identity matters.','Use the Steam game and its supported save features.'),('Which instructions apply?','PokeBonk menus, moves and League rules.','Megabonk guides for its own characters and systems.')])+f'<p>The comparison uses the original project’s entry/client and Megabonk’s Steam store. It is an access and progression comparison, not a performance test or a review score.{ref(1)}{ref(2)}{ref(3)}</p>'),
('transfer','What transfers from your Megabonk experience','<p>Reading a crowded arena, keeping room to move and checking what an upgrade actually changes are useful habits in either game. The build details need to be learned again. A familiar survival loop does not make a Megabonk weapon combination a PokeBonk recipe.</p><p>In PokeBonk, start with the partner’s listed passive and move kit. Connect the offered upgrade to that kit rather than looking for a Tome or item name from the Steam game. For example, a Fire-specific bonus needs a Fire move; the general idea of “more damage” is not enough to identify what it improves.</p>'),
('identity','Check the video before following its guide','<ul><li><strong>Pokémon partners and a browser entry:</strong> check the original PokeBonk website.</li><li><strong>Megabonk characters, Steam and weapons/Tomes:</strong> use the Megabonk Wiki.</li><li><strong>PokeSurvivor or another similar name:</strong> verify the actual project URL and interface. Similar search wording is not proof that its stats, evolutions or controls belong to PokeBonk.</li></ul><p>We do not identify every “Pokémon survivor” game as the same project. This page’s PokeBonk evidence is tied specifically to pokebonk.com.</p>'),
('choose','Choose the next step',f'<p><strong>Want the Pokémon browser game?</strong> Begin with Guest or your existing account at the original page, then use this section’s first-run guide. Keep your browser profile if you already have Guest progress.{ref(1)}</p><p><strong>Want the Steam game?</strong> Return to the <a href="/guides/megabonk-beginners-guide">Megabonk beginner guide</a> or <a href="/guides/builds/">Megabonk builds</a>. Those pages describe that game’s own progression.</p><p><strong>Want shared co-op?</strong> Check the actual game and current release first. A multiplayer mod for the Steam game does not establish multiplayer in the separate browser project.</p>')],
[('https://pokebonk.com/?lang=en','Original PokeBonk entry','Browser project and current guest entry, October 23.'),('https://store.steampowered.com/app/3405340/Megabonk/','Megabonk Steam store','Developer/publisher, game description and supported entry point, October 23.'),(CLIENT,'PokeBonk public client','League partner, passive and move UI, v0.8.25. SINGLE_SOURCE for current mechanics.')],
[('beginners-guide/','Begin PokeBonk'),('starters/','Choose a partner'),('multiplayer/','Check online feature claims')])

article('zh/beginners-guide','PokeBonk攻略：原站入口、御三家与新手操作','PokeBonk 新手攻略',
'找到 PokeBonk 原站入口，了解游客存档、御三家选择与默认按键，区分手机浏览器、APK 和联机功能。',
f'PokeBonk 是在浏览器里运行的宝可梦同人幸存者游戏。先进入原站，再选择游客或已有账号；不要把 Megabonk 的模组安装教程当成这款游戏的启动方法。本文依据当前菜单与公开客户端整理，没有冒称通关实测。{ref(1)}',[
('start','先找到游戏，再保留已有存档',f'<p>打开 {ext("https://pokebonk.com/?lang=zh","pokebonk.com — 简体中文原站入口")}。原站提供语言切换；中文与繁体中文是不同选项。页面需要 JavaScript 和 WebGL。若已有游客进度，优先在原来的浏览器和用户配置中进入。{ref(1)}</p><ol><li>首次进入时查看 Guest／游客、Enter／登录与 Create account／创建账号几个入口。</li><li>没有旧进度时可选择游客；有账号时使用登录，避免重新开一个游客身份。</li><li>按当前菜单选择初始伙伴，在 League／联盟中查看被动与技能，再进入地区、模式和难度选择。</li><li>进入前先查看 Settings／设置中的 Keys／按键，确认自己是否改过键位。</li></ol><p class="note">本次直接检查了入口菜单；后续流程根据公开客户端整理。没有完成游客转换、账号恢复或真实手机性能测试，按钮文案以你当前语言和版本为准。</p>'),
('partner','御三家怎么选',f'<p>先按你想练的方向选，不必把未经实测的字母榜当结论。下列是 v0.8.25 的被动与技能方向推导，不代表胜率排名。{ref(2)}{ref(3)}</p>'+table(['伙伴','当前被动重点','选择时看什么'],[('妙蛙种子 Bulbasaur','+1.5 生命再生、+25% 治疗；草系命中有受频率限制的回复。','想练持续恢复时考虑；不是每一个视觉弹体都能无限回血。'),('杰尼龟 Squirtle','+15 护甲、+20 护盾；生命低于40%时另有伤害加成。','想先学习走位和防御收益时考虑，不建议为了增伤故意掉血。'),('小火龙 Charmander','+10% 火系伤害；生命低于40%时有伤害加成。','想围绕火系技能读升级卡时考虑；不能据此断言通关最快。')])+'<p>完整技能组、被动数值与按目标筛选工具放在英文伙伴对比页；这些技能属于本游戏，不能直接套用宝可梦正作的强度结论。</p>'),
('keys','默认操作速查',f'<p>当前默认值是 WASD 移动、空格跳跃、左 Shift 滑行、E 交互、R 大招、Q 切换瞄准、鼠标右键锁定、M 地图、P 暂停。升级时 F／X／Z 分别用于当前可用的刷新、跳过与放逐。保存过的改键优先。{ref(2)}</p><p>角色的装备技能会自动攻击，但仍要控制移动、镜头、瞄准与升级选择。第一次先弄清“移动方向是否跟随镜头”和“附近是否出现交互提示”，再考虑复杂构筑。升级卡先看影响的技能类型或属性，不要只按颜色猜。</p>'),
('phone','手机、APK 与联机要分开看',f'<p>手机先打开原站浏览器版本。客户端包含触控操作，并不等于所有 iPhone、安卓机型都有流畅运行保证。本次没有验证官方 APK 或 App Store 发行；第三方套壳也不能当成官方安装包。{ref(1)}{ref(2)}</p><p>好友、社团和排行榜属于已能从当前资料确认的在线功能；它们不能自动证明可以进入同一张地图实时合作。本次没有验证共享合作局，不承诺上线时间或人数。</p><p>游客账号连续60天未使用会按项目政策删除。清理浏览器数据之前，先检查把现有游客保存为账号的选项；本攻略不能替你恢复账号。{ref(4)}</p><p>游戏问题可向 {ext("https://discord.gg/X7KusQqx8X","原项目 Discord 支持")} 提交版本、浏览器和错误信息；本站内容纠错请使用页脚 Contact，不要发送游戏密码。</p>')],
[('https://pokebonk.com/?lang=zh','原站中文入口','2026-10-23 核对；语言入口、运行前提与项目身份。'),(CLIENT,'原站当前公开客户端','v0.8.25，默认键位、触控与被动。SINGLE_SOURCE，非实测胜率。'),(NEWS,'原站共享客户端中的联盟定义','初始伙伴及技能组，build mvjzbutg。'),('https://pokebonk.com/legal','原项目隐私与游客政策','游客闲置60天政策与浏览器会话说明；未做恢复或期限实测。')],
[('beginners-guide/','English first-run guide'),('starters/','御三家完整技能对比（英文）'),('mobile/','手机浏览器与 APK 问题（英文）')],lang='zh-Hans')

def card(num,title,text,slug,featured=False):
    return f'<article class="card {"featured" if featured else ""}"><span class="number">FIELD NOTE {num}</span><h3>{title}</h3><p>{text}</p><a href="{P+slug}">Open guide →</a></article>'

def home():
    title='PokeBonk Guide: Starters, Controls & Browser Play'
    desc='Find the original PokeBonk browser game, compare starter roles, learn current controls and explore mobile, Guest progress and online feature guides.'
    body=f'''<section class="hero" id="guide"><div><span class="tag">Independent guide · Browser adventure</span><h1>PokeBonk.<br><em>Big adventure.</em></h1><p class="lead"><strong>PokeBonk</strong> brings Pokémon partners into a free 3D horde-survival game. Find the original browser game, choose a starter and make sense of your first run.{ref(1)}</p><div class="actions">{ext('https://pokebonk.com/?lang=en','Play at pokebonk.com')}<a class="button" href="{P}beginners-guide/">Plan your first run →</a></div><p class="meta">An unofficial fan game by Charcher. This is an independent guide.<br>Source check: {DATE} · Beta v0.8.25</p></div><figure class="hero-art"><img src="{A}forest-1280.webp" srcset="{A}forest-800.webp 800w, {A}forest-1280.webp 1280w" sizes="(max-width:900px) 100vw, 600px" width="1280" height="672" alt="PokeBonk promotional artwork showing a forest, waterfall and stone altar"><figcaption>Official promotional artwork © Charcher / respective rights holders. Not a gameplay screenshot.</figcaption></figure></section>
<div class="statusbar"><div><small>Where to play</small><strong>In your browser</strong></div><div><small>Entry</small><strong>Free fan game</strong></div><div><small>Starting partners</small><strong>Three distinct roles</strong></div><div><small>Source scope</small><strong>Beta v0.8.25</strong></div></div>
<section class="section" id="start"><div class="section-head"><div><p class="eyebrow">01 / Begin the journey</p><h2>A good first run starts here.</h2></div><p>Find the right entry, keep your progress and learn the buttons before chasing a build.</p></div><div class="grid">{card('01','New trainer? Start here.','Guest entry, current keyboard defaults and what to read on your first upgrade cards.','beginners-guide/',True)}{card('02','Take it to your phone.','Browser play, touch controls, APK questions and device limits in one place.','mobile/')}{card('03','中文入门攻略','从原站入口、御三家选择到按键与游客存档，按顺序开始。','zh/beginners-guide/')}</div></section>
<section class="section split" id="choose"><div><p class="eyebrow">02 / Choose your companion</p><h2>Pick a role.<br>Learn your partner.</h2><p>Bulbasaur’s listed passive supports recovery. Squirtle adds armor and shield. Charmander points toward Fire damage. Pick the role you want to learn; these are not measured strength tiers.{ref(2)}</p><a class="button secondary" href="{P}starters/">Compare moves &amp; passives →</a></div><div class="card featured"><h3>Looking for a tier list?</h3><p>Start with what the ranking measures. A passive comparison can explain a first pick; a claim about the strongest Pokémon needs comparable performance evidence.</p><p>Our starter comparison includes the current four-move kits and a goal selector. No invented win rates.</p><a href="{P}starters/#tier-list">How to read strength claims →</a></div></section>
<section class="section split" id="help"><div class="card"><p class="eyebrow">03 / Play &amp; connect</p><h2>Online does not always mean co-op.</h2><p>The current sources document friends, clans and rankings. A shared co-op run was not verified in this review. Check the actual feature before planning a session.</p><a href="{P}multiplayer/">Read the multiplayer status →</a></div><div class="card"><h3>Browser first. Keep your Guest.</h3><p>No installer is needed for the original browser entry. Before clearing site data, check the current Guest-saving options. The project’s policy deletes Guest accounts after 60 days without use.{ref(3)}</p><a href="{P}mobile/#apk">Android, iPhone &amp; APK questions →</a></div></section>
<section class="section" id="compare"><div class="compare-panel"><p class="eyebrow" style="color:#f6ca57">Coming from the Megabonk Wiki?</p><h2>The survival loop feels familiar.<br>The game rules are its own.</h2><p>Searching for “Megabonk Pokémon”? PokeBonk has its own browser client, League partners and progress. Megabonk’s builds and mod instructions describe the Steam game.</p><a href="{P}megabonk-vs-pokebonk/">PokeBonk vs Megabonk: find the right game →</a></div></section>
<section class="section" id="guides"><p class="eyebrow">Your field notebook</p><h2>Find your next answer.</h2><div class="guide-index"><a href="{P}beginners-guide/">Beginner guide<span>Entry → controls → upgrades → Guest progress</span></a><a href="{P}starters/">Starter comparison<span>Three passives, move kits and a goal selector</span></a><a href="{P}mobile/">Mobile &amp; APK guide<span>Browser setup and source-based device checks</span></a><a href="{P}multiplayer/">Online features<span>Clans, friends and co-op verification</span></a><a href="{P}megabonk-vs-pokebonk/">PokeBonk vs Megabonk<span>Choose the right project, client and guide</span></a><a href="{P}zh/beginners-guide/">PokeBonk 中文攻略<span>原站、初始伙伴、操作与存档注意事项</span></a></div></section>
<section class="section prose"><h2>A few things worth knowing</h2><h3>Is this the original game website?</h3><p>No. This is the PokeBonk guide section of Megabonk.org. The original browser game is at pokebonk.com.</p><h3>Is it an official Pokémon release?</h3><p>No. The project identifies itself as an unofficial, non-commercial fan game.{ref(3)}</p><h3>Is PokeSurvivor another name for it?</h3><p>No. JPTER78’s PokéSurvivor at pokesurvivor.com is a different browser project. PokeBonk is Charcher’s game at pokebonk.com; its controls, progression and accounts must be checked separately. <a href="/poke-survivor/">Find the PokéSurvivor game and player guides →</a> The original author identifies that project and domain (checked October 26, 2026).{ref(4)}</p>{source_list([('https://pokebonk.com/?lang=en','Original game entry','Browser access, project identity and current menu. Inspected October 23, 2026; v0.8.25.'),(CLIENT,'Original current client','Starter passives and online menus. SINGLE_SOURCE; no controlled gameplay or phone performance test.'),('https://pokebonk.com/legal','Project legal and privacy notice','Fan-project status and Guest policy, accessed October 23. Not a statement about this guide’s own privacy practices.'),('https://github.com/JPTER78/pokesurvivor','JPTER78 GitHub — PokéSurvivor original project','Original author and pokesurvivor.com identity, checked October 26, 2026. A different game from Charcher’s PokeBonk.')])}</section>'''
    PAGES[P]={'title':title,'desc':desc,'html':shell(P,title,desc,body)}

def legal(slug,title,desc,content):
    path=P+slug+'/'
    body=f'<nav class="crumbs" aria-label="Breadcrumb"><a href="{P}">PokeBonk</a> / {title}</nav><article class="legal" id="guide"><p class="eyebrow">Independent guide</p><h1>{title}</h1><p class="meta">Updated {DATE}</p>{content}</article>'
    PAGES[path]={'title':title+' | PokeBonk Guide','desc':desc,'html':shell(path,title+' | PokeBonk Guide',desc,body)}

def build():
    home()
    from pokebonk_updates import apply_updates
    apply_updates(globals())
    from pokebonk_completion import apply_completion
    apply_completion(globals())
    from pokebonk_access import apply_access
    apply_access(globals())
    from pokebonk_longtail import apply_longtail
    apply_longtail(globals())
    from pokebonk_tools import apply_tools
    apply_tools(globals())
    legal('about','About this guide','Learn who maintains the independent PokeBonk guide on Megabonk.org, how current sources are checked and how to request a correction.',f'<p>This PokeBonk section is maintained by the independent publisher of Megabonk.org. It helps players identify the original browser game and understand entry, starter choices and online features.</p><h2>How we work</h2><p>We inspect the original project’s public pages, current menus and publicly loaded game data. Guides distinguish source-based facts from editorial advice and retain dates, versions and material limits. A client definition is not a measured win rate or a phone compatibility test.</p><p>The October 23 review inspected Beta v0.8.25. We did not complete a controlled gameplay benchmark, a real-device mobile test, a Guest recovery or a shared co-op session. We do not label those as tested.</p><h2>Who owns the game?</h2><p>PokeBonk is a fan project led by Charcher. This guide is not operated by the game developer and is not affiliated with Nintendo, The Pokémon Company, Creatures or GAME FREAK. Game images and names belong to their respective rights holders. Our seed-compass navigation mark identifies this guide, not the game.</p><h2>Corrections and image requests</h2><p>Use our <a href="{P}contact/">contact page</a> with the URL, the disputed detail and a current source. Rights holders can use the same address for image or content requests.</p><p><a href="{P}#guides">Browse all guides →</a></p>')
    mail='mailto:qsyhxw@gmail.com?subject=%5BMegabonk.org%5D%20Website%20feedback'
    legal('contact','Contact','Send corrections, source updates or image requests to the publisher of the PokeBonk guide on Megabonk.org, or find the original project support.',f'<p>For this guide’s corrections, broken links, source updates or image requests, email <a href="{mail}">qsyhxw@gmail.com</a>.</p><h2>Help us check the right detail</h2><ul><li>The guide URL and the sentence or image concerned.</li><li>The game version and date if a mechanic changed.</li><li>A public project announcement, screenshot or other source that supports the correction.</li></ul><p>There is no on-site submission form. Your email provider opens when you select the address. We do not promise a response time.</p><h2>Game accounts and support</h2><p>We cannot reset passwords, restore Guests, resolve suspensions or inspect the game’s database. For game support use {ext("https://discord.gg/X7KusQqx8X","the original project’s Discord")}, linked from the original website. Never send us game passwords or authentication data.</p><h2>Personal information</h2><p>Only include details needed to explain the issue. See the <a href="{P}privacy/">privacy notice</a> for how contact email and this website are handled.</p>')
    legal('privacy','Privacy notice','Read how the PokeBonk guide handles hosting requests and contact email, and how its privacy practices differ from the original browser game.',f'<p>This notice covers the PokeBonk guide section at megabonk.org/pokebonk/. It is separate from the privacy policy of the original game at pokebonk.com.</p><h2>Website delivery</h2><p>The website is delivered through Cloudflare. Delivery and security services may process request data such as IP address, browser information and the requested URL. Cloudflare may apply security checks at its edge. See {ext("https://www.cloudflare.com/privacypolicy/","Cloudflare’s privacy policy")}.</p><h2>Scripts and browser storage</h2><p>The PokeBonk homepage and gameplay guides load Google AdSense. Google and its advertising partners may make third-party requests and use cookies or device information to deliver and measure advertisements. About, Contact, this privacy page and error pages do not load our AdSense code. This section adds no analytics tags. The starter selector, reference-table filters and fusion pair finder run locally. They do not submit your selections or store them. Partner search, build planning and Lab budgets also run locally. Build share links encode the selected partner, moves, goal, capacity, item copies, vitamins and declared owned Lab levels in the URL; anyone you share that link with can read those choices. They contain no game credentials and do not change your game account. Fonts and images are hosted with this website. Edge-delivery services may add their own operational behavior.</p><p>Other Megabonk.org pages use Cloudflare Web Analytics, Google Analytics and Google advertising services and have a separate <a href="/privacy-policy">site-wide privacy notice</a>. Following a link out of this section can therefore load different services. This notice does not claim that the entire domain is free of third-party scripts.</p><h2>Advertising choices</h2><p>You can manage Google advertising preferences through {ext("https://myadcenter.google.com/", "Google My Ad Center")}. Applicable consent choices may also be provided by Google’s consent messages. See {ext("https://policies.google.com/technologies/ads", "Google’s advertising privacy explanation")} for how advertising information is used.</p><h2>Contact email</h2><p>If you email qsyhxw@gmail.com, Gmail processes the message and the publisher receives the sender address and whatever details you include. Messages are used to handle the request. Do not include game passwords or unnecessary personal data. You may email the same address to request removal of correspondence, subject to any necessary record retention.</p><h2>External websites</h2><p>The original game, Discord and Steam apply their own terms and privacy practices. Opening the original game may create game-related browser storage or a server account; this guide does not operate that system. See {ext("https://pokebonk.com/legal","the original project’s privacy notice")}.</p><h2>Questions or corrections</h2><p>Use our <a href="{P}contact/">contact page</a>. This notice will be revised if this section adds services that change the practices described here.</p>')
    from pokebonk_play import add_play
    add_play(globals())
    from pokebonk_depth import apply_depth
    apply_depth(globals())
    from pokebonk_compare import apply_compare
    apply_compare(globals())
    error=f'<nav class="crumbs" aria-label="Breadcrumb"><a href="{P}">PokeBonk</a> / 404</nav><section class="legal"><p class="eyebrow">404 / Off the trail</p><h1>This path ends here.</h1><p>The page may have moved, or the address may be incomplete. Your next guide is still on the map.</p><div class="actions"><a class="button" href="{P}">Back to PokeBonk →</a><a class="button secondary" href="{P}#guides">Browse the guides</a></div></section>'
    out=ROOT/'pokebonk/404.html';out.parent.mkdir(exist_ok=True);out.write_text(shell(P+'404','Page not found | PokeBonk Guide','This PokeBonk guide path could not be found. Return to the guide homepage or browse the available player notes.',error,noindex=True),encoding='utf-8')
    for path,page in PAGES.items():
        file=ROOT/path.lstrip('/')/'index.html';file.parent.mkdir(parents=True,exist_ok=True);file.write_text(page['html'],encoding='utf-8')
    print(json.dumps([{'url':p,'title_length':len(v['title']),'description_length':len(v['desc'])} for p,v in PAGES.items()],indent=2))

if __name__=='__main__':build()
